def power_mod(base, exponent, modulus):
    return pow(base, exponent, modulus)

rem_500 = power_mod(3, 500, 10000)
rem_1000 = power_mod(3, 1000, 10000)
rem_1500 = power_mod(3, 1500, 10000)

print(f"3^500 mod 10000: {rem_500}")
print(f"3^1000 mod 10000: {rem_1000}")
print(f"3^1500 mod 10000: {rem_1500}")

if rem_500 == rem_1000 and rem_1000 == rem_1500:
    print("All remainders are the same.")
else:
    print("Remainders are different.")
